import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner sc=new Scanner(System.in);
		int t= sc.nextInt();
		while(t-- >0){
		    int n=sc.nextInt();
		    int totalStudents=3*n;
		    long [] a=new long[totalStudents];
		    for(int i=0;i<totalStudents;i++){
		        a[i]=sc.nextLong();
		        
		    }
		    Arrays.sort(a);
		    long[] r=new long[totalStudents];
		    for(int i=0;i<totalStudents;i++){
		        r[i]=a[totalStudents-1-i];
		    }
		    long[] pref=new long[totalStudents+1];
		    for(int i=0;i<totalStudents;i++){
		        pref[i+1]=pref[i]+r[i];
		    }
		    long answer=0;
		    for(int A=0;A<=n;A++)
		    {
		        int maxB=n-A;
		        int low=0;
		        int high=maxB;
		        while(low<high){
		            int B=(low+high)/2;
		            int q=A+2*B;
		            int last=3*n-2*A-B-1;
		            long change=r[q]+r[q+1]-3*r[last];
		            if(change>0){
		                low=B+1;
		            }
		            else{
		                high=B;
		            }
		        }
		        for(int B=Math.max(0,low-1);B<=Math.min(maxB,low+1);B++){
		            int C=n-A-B;
		            int q=A+2*B;
		            int and=q+3*C;
		            long value=0;
		            value+= 6L*pref[A];
		            value+= 4L*(pref[q]-pref[A]);
		            value+= 3L*(pref[and]-pref[q]);
		            answer=Math.max(answer,value);
		        }
		    }
		    System.out.println(answer);
		    
		}
		sc.close();
	}
}
